"""Bind all 43 trainable posture/timing outputs to the verified >=2m seed."""
from pathlib import Path
import argparse,json,time,subprocess,sys
import numpy as np,torch
from stable_baselines3 import PPO
from stable_baselines3.common.vec_env import DummyVecEnv
from recover_jump_ppo_batch import SetupOnlyEnv
ROOT=Path(__file__).resolve().parents[1]
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--wait',action='store_true');a=ap.parse_args();root=ROOT/'results/controlled_broad_jump/two_metre_initial_solution_verified';verify=root/'verification.json'
 while not verify.exists():
  if not a.wait:raise FileNotFoundError(verify)
  time.sleep(5)
 verified=json.loads(verify.read_text());assert verified['status']=='passed';source=Path(verified['cases'][-1]['folder']);out=ROOT/'deliverables/standing_long_jump_learning';worker_out=ROOT/'results/controlled_broad_jump/two_metre_full_policy_setup';worker_out.mkdir(exist_ok=True);log=(worker_out/'worker.log').open('w');worker=subprocess.Popen([sys.executable,str(ROOT/'scripts/jump_parameter_rl_worker.py'),'--source',str(source),'--out',str(worker_out),'--stage','full','--capacity-file',str(root/'fixed_virtual_capacity.json'),'--dt',str(verified['cases'][0]['dt_s'])],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,text=True,encoding='utf-8',creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0));line=worker.stdout.readline();assert line.startswith('RL_WORKER_READY '),line;definition=json.loads(line.split(' ',1)[1]);assert len(definition['actions'])==43;worker.stdin.write(json.dumps(dict(cmd='rollout',kind='baseline',action=[0.]*43))+'\n');worker.stdin.flush();line=worker.stdout.readline();assert line.startswith('RL_RESULT '),line;result=json.loads(line.split(' ',1)[1]);worker.stdin.write('{"cmd":"close"}\n');worker.stdin.flush();worker.wait(timeout=20);log.close();assert result['stable']and result['contact_distance_m']>=2.,result;coarse=verified['cases'][0]['valid_contact_distance_m'];replay_error=abs(coarse-result['contact_distance_m']);assert replay_error<1e-6,replay_error
 torch.set_num_threads(1);torch.manual_seed(23);obs=np.array(definition['observation'],np.float32);env=DummyVecEnv([lambda:SetupOnlyEnv(obs,43)]);model=PPO('MlpPolicy',env,learning_rate=.001,n_steps=8,batch_size=8,n_epochs=4,gamma=1.,gae_lambda=1.,clip_range=.15,ent_coef=.001,target_kl=.02,policy_kwargs=dict(net_arch=dict(pi=[32,32],vf=[32,32]),activation_fn=torch.nn.Tanh,log_std_init=float(np.log(.08))),device='cpu',seed=23,verbose=0)
 with torch.no_grad():model.policy.action_net.weight.zero_();model.policy.action_net.bias.zero_()
 mean,_=model.predict(obs,deterministic=True);assert np.max(abs(mean))==0 and all(p.requires_grad for p in model.policy.parameters());model.save(out/'two_metre_policy_initial');report=dict(status='initialized_on_verified_two_metre_motion',actor=[7,32,32,43],critic=[7,32,32,1],all_posture_and_timing_outputs_jointly_trainable=True,all_43_standard_deviations_trainable=True,initial_normalized_std=.08,policy_mean='Zero offset maps to the complete verified initial motion.',baseline_supported_distance_at_search_dt_m=result['contact_distance_m'],baseline_replay_error_m=replay_error,source=str(source),parameter_definition=definition,checkpoint='two_metre_policy_initial.zip',training_episodes=0,initial_solution_search_is_separate_from_PPO=True,one_action_selects_a_complete_jump=True,framewise_motor_policy=False,physical_conditions_fixed=True,virtual_capacity_basis='Net virtual joint torque; one shared fixed profile for compared postures, not measured human maximum strength.');(out/'two_metre_full_policy_setup.json').write_text(json.dumps(report,indent=2));print('TWO_METRE_FULL_POLICY_READY',result['contact_distance_m'],'43 trainable outputs; no PPO training yet',flush=True)
if __name__=='__main__':main()
